// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout, MatrixTriangle } from '@stdlib/types/blas';

/**
* Conversion direction.
*/
type Way = 'convert' | 'revert';

/**
* Interface describing `dsyconvfRook`.
*/
interface Routine {
	/**
	* Converts or reverts symmetric indefinite rook-factor storage in place.
	*
	* ## Notes
	*
	* -   `IPIV` is read-only, signed, and 1-based, exactly as in LAPACK.
	* -   Distinct adjacent negative pivots identify a 2x2 block; `-1` retains the first-row target and block marker.
	* -   Conversion writes `E`; reversion leaves `E` unchanged.
	* -   The full matrix and vector indexed-byte envelopes must be disjoint.
	* -   For N greater than zero, each actual typed-array backing store must be an ordinary ArrayBuffer; SharedArrayBuffer-backed views are rejected before routine-owned writes.
	* -   Exotic ArrayBuffers whose physical storage is externally aliased by foreign native addons are outside the caller contract.
	* -   The declared typed-array types cannot express this runtime backing-store precondition.
	*
	* @param order - row-major or column-major storage
	* @param uplo - stored matrix triangle
	* @param way - conversion direction
	* @param N - matrix order (nonnegative safe integer not exceeding 2147483647)
	* @param A - input/output matrix
	* @param LDA - leading dimension, at least max(1,N)
	* @param E - off-diagonal block values (output for conversion, input for reversion)
	* @param IPIV - read-only signed 1-based LAPACK rook pivots
	* @throws selectors and active buffer types must be valid
	* @throws dimensions, bounds, aliasing, and pivots must satisfy the documented preconditions
	* @returns zero on success
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var A = new Float64Array( [ 0.0, 2.0, 999.0, 0.0 ] );
	* var E = new Float64Array( 2 );
	* var IPIV = new Int32Array( [ -1, -2 ] );
	*
	* var info = dsyconvfRook( 'row-major', 'upper', 'convert', 2, A, 2, E, IPIV );
	* // returns 0
	* // A => <Float64Array>[ 0.0, 0.0, 999.0, 0.0 ]
	* // E => <Float64Array>[ 0.0, 2.0 ]
	*/
	( order: Layout, uplo: MatrixTriangle, way: Way, N: number, A: Float64Array, LDA: number, E: Float64Array, IPIV: Int32Array ): number;

	/**
	* Converts or reverts rook-factor storage using alternative indexing semantics.
	*
	* ## Notes
	*
	* -   All strides and offsets are element indices relative to their typed-array views.
	* -   The full leading N-by-N matrix view must be injective and in bounds.
	* -   For N greater than one, the E stride must be nonzero in both directions.
	* -   Read-only IPIV may have zero stride if its complete repeated pivot sequence is structurally valid.
	* -   Positive and negative independent strides are supported.
	* -   Active arrays require ordinary ArrayBuffer backing stores; SharedArrayBuffer-backed views, including views of shared buffers returned by structuredClone, are rejected before routine-owned writes.
	* -   Externally aliased ArrayBuffers from foreign native addons are outside the caller contract; this runtime precondition cannot be expressed by the declared typed-array types.
	*
	* @param uplo - stored matrix triangle
	* @param way - conversion direction
	* @param N - matrix order
	* @param A - input/output matrix
	* @param strideA1 - matrix row stride
	* @param strideA2 - matrix column stride
	* @param offsetA - starting index for A
	* @param E - off-diagonal block values
	* @param strideE - E stride
	* @param offsetE - starting index for E
	* @param IPIV - read-only signed 1-based LAPACK rook pivots
	* @param strideIPIV - IPIV stride
	* @param offsetIPIV - starting index for IPIV
	* @throws selectors and active buffer types must be valid
	* @throws dimensions, metadata, bounds, aliasing, and pivots must satisfy the documented preconditions
	* @returns zero on success
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var A = new Float64Array( [ 7.0, 0.0, 2.0, 999.0, 0.0, 7.0 ] );
	* var E = new Float64Array( [ 8.0, 0.0, 0.0, 8.0 ] );
	* var IPIV = new Int32Array( [ 9, -1, -2, 9 ] );
	*
	* var info = dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, 1, 1, E, 1, 1, IPIV, 1, 1 );
	* // returns 0
	* // E => <Float64Array>[ 8.0, 0.0, 2.0, 8.0 ]
	*/
	ndarray( uplo: MatrixTriangle, way: Way, N: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, E: Float64Array, strideE: number, offsetE: number, IPIV: Int32Array, strideIPIV: number, offsetIPIV: number ): number;
}

/**
* Converts or reverts symmetric indefinite rook-factor storage in place.
*
* @param order - storage layout
* @param uplo - stored matrix triangle
* @param way - conversion direction
* @param N - matrix order
* @param A - input/output matrix
* @param LDA - leading dimension, at least max(1,N)
* @param E - off-diagonal block values
* @param IPIV - read-only signed 1-based LAPACK rook pivots
* @returns zero on success
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var A = new Float64Array( [ 0.0, 2.0, 999.0, 0.0 ] );
* var E = new Float64Array( 2 );
* var IPIV = new Int32Array( [ -1, -2 ] );
*
* dsyconvfRook( 'row-major', 'upper', 'convert', 2, A, 2, E, IPIV );
* // E => <Float64Array>[ 0.0, 2.0 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var A = new Float64Array( [ 0.0, 0.0, 999.0, 0.0 ] );
* var E = new Float64Array( [ 0.0, 2.0 ] );
* var IPIV = new Int32Array( [ -1, -2 ] );
*
* dsyconvfRook.ndarray( 'upper', 'revert', 2, A, 2, 1, 0, E, 1, 0, IPIV, 1, 0 );
* // A => <Float64Array>[ 0.0, 2.0, 999.0, 0.0 ]
*/
declare var dsyconvfRook: Routine;


// EXPORTS //

export = dsyconvfRook;
